import{_ as n,o as r,c as t,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/lehrkraefte/basisdaten-individualdaten.png",d="/bilder/lehrkraefte/basisdaten-kontaktdaten-2.png",s="/bilder/lehrkraefte/basisdaten-schild-relevante-daten.png",l="/bilder/lehrkraefte/basisdaten-bearbeitungswerkzeuge.png",c=JSON.parse('{"title":"Stamm- und Kontaktdaten der Lehrkräfte pflegen","description":"","frontmatter":{"title":"Stamm- und Kontaktdaten der Lehrkräfte pflegen","source_pageid":236,"source_revision":5307},"headers":[],"relativePath":"schild3/lehrkraefte/basisdaten-lehrkraefte.md","filePath":"schild3/lehrkraefte/basisdaten-lehrkraefte.md"}'),h={name:"schild3/lehrkraefte/basisdaten-lehrkraefte.md"};function o(u,e,p,k,g,f){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="stamm-und-kontaktdaten-der-lehrkrafte-pflegen" tabindex="-1">Stamm- und Kontaktdaten der Lehrkräfte pflegen <a class="header-anchor" href="#stamm-und-kontaktdaten-der-lehrkrafte-pflegen" aria-label="Permalink to &quot;Stamm- und Kontaktdaten der Lehrkräfte pflegen&quot;">​</a></h1><p>Erfassen Sie persönliche Daten, Kontaktdaten und die für SchILD-NRW relevanten Merkmale der Lehrkräfte. Der Artikel beschreibt auch das Einbinden von Fotos.</p><p>Auf diesem Karteireiter werden die Stammdaten der Lehrerinnen und Lehrer verwaltet. Der Reiter gliedert sich in drei Bereiche, die Individualdaten, die Kontaktdaten und die für die Statistik relevanten Daten.</p><h2 id="individualdaten" tabindex="-1">Individualdaten <a class="header-anchor" href="#individualdaten" aria-label="Permalink to &quot;Individualdaten&quot;">​</a></h2><p><a href="/bilder/lehrkraefte/basisdaten-individualdaten.png"><img src="'+i+'" alt="Die Individualdaten der Lehrkräfte." loading="lazy"></a></p><p><em>Die Individualdaten der Lehrkräfte.</em></p><p>Die Individualdaten enthalten die persönlichen Daten der Lehrerinnen und Lehrer.</p><p>Neben der Amtsbezeichnung und der Anschrift können Sie hier auch eventuell vorhandene Titel und Amtsbezeichnungen eingeben.</p><p>Reports und viele Zeugnisformulare können diese Angaben übernehmen und ausgeben.</p><h2 id="kontaktdaten" tabindex="-1">Kontaktdaten <a class="header-anchor" href="#kontaktdaten" aria-label="Permalink to &quot;Kontaktdaten&quot;">​</a></h2><p><a href="/bilder/lehrkraefte/basisdaten-kontaktdaten-2.png"><img src="'+d+'" alt="Daten zum E-Mailversand an Lehrkräfte." loading="lazy"></a></p><p><em>Daten zum E-Mailversand an Lehrkräfte.</em></p><p>Die Kontaktdaten beinhalten Angaben zu Telefonnummern und E-Mail-Adressen. Sie sind wichtig, wenn Sie über Lehrerreports auch Listen für das Kollegium erstellen wollen.</p><p>Wenn eine E-Mail-Adresse eingetragen ist, kann mit einem Doppelklick eine E-Mail versendet werden.</p><p>Der Versand kann auch an mehrere Lehrerinnen und Lehrer gleichzeitig erfolgen, wenn diese zuvor markiert wurden.</p><h2 id="fur-schild-nrw-relevante-daten" tabindex="-1">Für SchILD-NRW relevante Daten <a class="header-anchor" href="#fur-schild-nrw-relevante-daten" aria-label="Permalink to &quot;Für SchILD-NRW relevante Daten&quot;">​</a></h2><p><a href="/bilder/lehrkraefte/basisdaten-schild-relevante-daten.png"><img src="'+s+'" alt="Statistik-relevante Daten zu Lehrkräften." loading="lazy"></a></p><p><em>Statistik-relevante Daten zu Lehrkräften.</em></p><p>Der Haken bei <strong>relevant für Statistik</strong> steuert, ob der Lehrerdatensatz in die Statistik-Datei geschrieben wird.</p><p>Prüfen Sie die Meldepflicht anhand der aktuellen Erhebungsvorgaben für Ihre Schulform und Personengruppe. Die Finanzierung durch einen anderen Träger allein ist kein ausreichender Grund, einen Datensatz von der Meldung auszunehmen.</p><p>Das Feld <strong>Kann folgende Fächer unterrichten</strong> ist ein frei definierbares Textfeld, auf das Sie im Reporting zurückgreifen können. Damit ist es zum Beispiel möglich, über einen Report die Lehrerinnen und Lehrer nach Fächern zuzuordnen.</p><p>In SchILD-NRW sind mit diesem Feld jedoch zur Zeit keine weiteren Funktionen verknüpft, so dass Sie sich die Eingabemethode selbst aussuchen können.</p><p>Es wird empfohlen die Eingabe nach internem Fachkürzel und mit Komma getrennt vorzunehmen, da einige Reports aus der Downloadsammlung diese Notation erwarten (Beispiel: &quot;D,E,PH&quot;).</p><p>Erfassen Sie <strong>Lehrbefähigungen</strong> unter <strong>Schulbezogene Daten</strong>. Dort werden sie für die Statistik und die weitere Verarbeitung gespeichert. Verwenden Sie dafür nicht das freie Feld <strong>Kann folgende Fächer unterrichten</strong>.</p><h2 id="fotos-einbinden" tabindex="-1">Fotos einbinden <a class="header-anchor" href="#fotos-einbinden" aria-label="Permalink to &quot;Fotos einbinden&quot;">​</a></h2><p><a href="/bilder/lehrkraefte/basisdaten-bearbeitungswerkzeuge.png"><img src="'+l+'" alt="Foto bearbeiten" loading="lazy"></a></p><p><em>Foto bearbeiten</em></p><p>Fotos von Lehrerinnen und Lehrern können über den Kamera-Button eingebunden werden.</p><p>Bitte beachten Sie dabei, dass die Bilder (möglichst im jpg-Format) vorher in eine sinnvolle Größe gebracht werden.</p><p>Über den Button mit dem Radiergummi werden Fotos gelöscht. Der Button mit dem Pinsel öffnet ein Fenster mit vier Bearbeitungsmöglichkeiten (Helligkeit, Kontrast, Sättigung und Drehung).</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Basisdaten_(Lehrkr%C3%A4fte)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5307.</p>',32)])])}const b=n(h,[["render",o]]);export{c as __pageData,b as default};
